values
  ('spot_shrimp', null, 'wa-ma-5-13-inside', 'salt', 'bag_limit', 'Puget Sound (Marine Areas 5-13 and Marine Area 4 east of the Bonilla-Tatoosh line): Daily limit of 80 spot shrimp. Daily limit of 10 pounds, heads and tails, of all shrimp species combined (maximum of 80 spot shrimp — if open for spot shrimp). First opening date will occur in May.', 'https://www.eregulations.com/washington/fishing/shrimp-rules', 'WDFW — 2026-2027 Washington Sport Fishing Rules (Shrimp Rules)', '2026-06-18', '2026-09-02', 5,
   null, null, 80, null, null, null, null, null, 'Capped inside a 10-lb all-species combined daily limit; first opening occurs in May (dates announced late March/early April).', true, 7),
  (null, null, 'wa-ma-5-13-inside', 'salt', 'gear', 'Shrimp (Puget Sound): minimum mesh size for shrimp pots is 1" mesh. June 1 through October 15: minimum mesh is 1", unless the area is closed for spot shrimp but open for coonstripe and pink shrimp, then minimum mesh is ½"; in those areas all spot shrimp caught must be returned to the water immediately. If retaining non-spot shrimp, all shrimp heads (spot and non-spot) must be retained in the field until ashore and finished fishing for the day. All Areas: each harvester must have a separate container for their catch; no minimum carapace size; maximum of two shrimp pots per person, no more than four shrimp pots per boat.', 'https://www.eregulations.com/washington/fishing/shrimp-rules', 'WDFW — 2026-2027 Washington Sport Fishing Rules (Shrimp Rules)', '2026-06-18', '2026-09-02', 5,
   null, null, null, null, null, null, null, null, null, true, 30),
  (null, null, 'wa-ma-5-13-inside', 'salt', 'season', 'Marine Areas 4 (east of Bonilla-Tatoosh line), 5, 6, 7 East, 7 South, 7 West, 8-1, 8-2, 9, 10, 11, 12, Discovery Bay Shrimp Area: For shrimp season open dates and times go to wdfw.wa.gov/fishing/shellfishing-regulations/shrimp/areas. The dates for the upcoming 2027 season will be announced and available in late March or early April to accommodate co-management obligations, account for extreme tides, and complete pre-season test fishing and quota setting. Discovery Bay Shrimp Area: waters south of a line from McCurdy Point on the Quimper Peninsula to the northern tip of Protection Island then to Rocky Point on the Miller Peninsula and all waters of Discovery Bay.', 'https://www.eregulations.com/washington/fishing/shrimp-rules', 'WDFW — 2026-2027 Washington Sport Fishing Rules (Shrimp Rules)', '2026-06-18', '2026-09-02', 5,
