   null, null, 0, 0, null, null, null, null, null, true, 7),
  ('spot_shrimp', null, 'wa-ma-13', 'salt', 'prohibited', 'During 2026 Marine Areas 8-1, 8-2, 9, 10, 11, and 13 have been CLOSED to spot shrimp harvest.', 'https://www.eregulations.com/washington/fishing/shrimp-rules', 'WDFW — 2026-2027 Washington Sport Fishing Rules (Shrimp Rules)', '2026-06-18', '2026-09-02', 5,
   null, null, 0, 0, null, null, null, null, null, true, 7),
  (null, null, 'wa-ma-1-4-coastal', 'salt', 'bag_limit', 'Pacific Ocean (Marine Areas 1-3 and Marine Area 4 west of the Bonilla-Tatoosh line): Daily limit of 25 pounds, heads and tails, of all shrimp species combined (maximum of 200 spot shrimp). Shrimp heads may be removed, but must be retained while in the field, until ashore and finished fishing for the day. The minimum mesh size for shrimp pots is 1" mesh.', 'https://www.eregulations.com/washington/fishing/shrimp-rules', 'WDFW — 2026-2027 Washington Sport Fishing Rules (Shrimp Rules)', '2026-06-18', '2026-09-02', 5,
